/*
 * td_py.h - the `py` command: MicroPython scripts in TinyDesk Shell.
 *
 * The interpreter is third_party/micropython (generated by
 * tools/micropython). An application can add modules of its own: C files
 * with MP_REGISTER_MODULE and frozen Python, listed when it generates its
 * own headers with tools/micropython (see python/README.md).
 */
#ifndef TD_PY_H
#define TD_PY_H

#include <stdbool.h>

#include "tdsh.h"

/* Register `py` with TinyDesk Shell (call once, before sessions start). */
int td_py_register_shell_command(void);

/* Ctrl+C: a function that returns true once the user pressed it on the
 * console running the script (the same check `modbus read -i` uses). Without
 * one, a running script cannot be stopped from the keyboard. */
void td_py_set_break_check(bool (*fn)(void));

/* Optional, for consoles that need them: where the prompt and input() read
 * a key (blocking; EOF at the end of input; default getchar()), and a
 * function called with true before a script or the prompt runs and false
 * after (a PC terminal goes into raw mode, so the prompt edits its own
 * line and Ctrl+C arrives as a key). */
void td_py_set_console(int (*read_key)(void), void (*raw_mode)(bool on));

/* For td_py_vfs.c and application modules: the session running the script. */
tdsh_session_t *td_py_session(void);

/* For applications that add modules of their own (a desktop's windows,
 * say): something to run after every script, while the interpreter is
 * still up, to release what the script left behind. At most 4; returns 0,
 * or -1 when full. */
int td_py_add_cleanup(void (*fn)(void));

/* The text help() prints with no argument. The shell's describes its own
 * modules; an application with modules of its own defines this array
 * itself and builds td_py.c with TD_PY_APP_HELP (HELP_EXTERNAL in
 * tdsh_add_python and tdsh_micropython_component). */
extern const char td_py_help_text[];

#endif /* TD_PY_H */
